-- ARC personalized why-this-matters content rules
-- Generated for production recommendation copy generation.
-- This table prevents generic UI copy such as "this answer increases relevance"
-- and gives the code agent a dependency layer between user answers and human explanations.

DROP TABLE IF EXISTS check_why_this_matters_rules;

CREATE TABLE check_why_this_matters_rules (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    check_key TEXT NOT NULL,
    field_key TEXT NOT NULL,
    answer_option TEXT NOT NULL,
    test_bundle TEXT,
    trigger_type TEXT NOT NULL CHECK (trigger_type IN ('age','life_stage','goal','symptom','lifestyle','diet','condition','family_history','medication','recency')),
    trigger_key TEXT NOT NULL,
    priority_weight INTEGER NOT NULL CHECK (priority_weight BETWEEN 1 AND 10),
    merge_group TEXT NOT NULL CHECK (merge_group IN ('driver','modifier','context')),
    max_occurrences INTEGER NOT NULL DEFAULT 1,
    explanation_template TEXT NOT NULL,
    mechanism TEXT,
    test_focus TEXT,
    priority_rationale TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    UNIQUE(check_key, trigger_key)
);


DROP VIEW IF EXISTS v_check_why_this_matters_rules;

CREATE VIEW v_check_why_this_matters_rules AS
SELECT r.*, c.check_name
FROM check_why_this_matters_rules r
LEFT JOIN canonical_check_config c USING (check_key)
ORDER BY r.check_key, r.priority_weight DESC, r.trigger_type, r.answer_option;

-- Composer usage rule:
-- 1) Filter rows by matched user answer signals for the check.
-- 2) Sort by priority_weight DESC.
-- 3) Take max 2 driver rows, max 1 modifier row, max 1 context row.
-- 4) Merge into 1-2 sentences.
-- 5) Never render trigger_key, raw field_key, or the phrase "used as a profile signal".
